    return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-label="Detail pesanan"><div class="modal-head"><div><h2>Detail pesanan</h2><p>${o.id} · ${relativeDate(o.date)} ${o.time}</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="profile-header" style="padding:12px">${avatar(provider.avatar)}<div style="flex:1"><h2 style="font-size:13px">${escapeHtml(o.recipient)} · ${categories[o.type].label}</h2><p>${escapeHtml(provider.provider)} · ${o.route === "home" ? "Home Care" : "Partner Facility"}</p></div>${statusPill(o.status)}</div><div class="setting-row"><div><strong>${icon("calendar",12)} Jadwal & durasi</strong><span>${formatDate(o.date)} · ${o.time} · ${o.route === "facility" ? `${bookingDays(o)} hari · 1 slot/hari` : `${o.hours} jam/hari × ${bookingDays(o)} hari`}</span></div></div><div class="setting-row"><div><strong>${icon("pin",12)} ${o.route === "home" ? "Lokasi layanan" : "Fasilitas"}</strong><span>${escapeHtml(o.route === "home" ? o.address : f?.name || o.area)}</span></div></div><div class="receipt"><div class="summary-line"><span>Biaya layanan</span><strong>${money(o.servicePrice)}</strong></div><div class="summary-line"><span>Platform fee CareNest (10%)</span><strong>${money(o.fee)}</strong></div><div class="summary-total"><span>Total</span><strong>${money(o.total)}</strong></div><div class="setting-row"><div><strong>Status escrow simulasi</strong><span>${escapeHtml(o.payment)}</span></div>${statusPill(o.payment)}</div></div><h3 style="font-size:11px;margin:14px 0 6px">Care plan (${o.tasks.length} task)</h3><div class="modal-points">${o.tasks.map(t=>`<div class="task-option">${t.done?"✓":"○"} ${escapeHtml(t.label)} ${t.evidenceRequired?"· Bukti diminta":""}</div>`).join("")}${o.plan?`<p class="muted" style="font-size:9px">Instruksi: ${escapeHtml(o.plan)}</p>`:""}</div>${audit.length?`<h3 style="font-size:11px;margin:14px 0 6px">Riwayat perubahan</h3><div class="modal-points">${audit.map(entry=>`<div class="task-option"><span class="status">${new Intl.DateTimeFormat("id-ID",{hour:"2-digit",minute:"2-digit",day:"numeric",month:"short"}).format(new Date(entry.at))}</span>${escapeHtml(entry.event)} · ${escapeHtml(entry.actor)}</div>`).join("")}</div>`:""}<div class="inline-notice green">${icon("shieldCheck",14)} Kontak langsung dimasking sebelum pesanan dikonfirmasi. Dukungan dispute dan riwayat care tersedia di platform.</div><div class="modal-actions">${o.status === "Dikonfirmasi" ? `<button class="button danger" data-action="cancel-order" data-id="${o.id}">Batalkan</button>` : ""}<button class="button secondary" data-action="repeat-order" data-id="${o.id}">${icon("calendar",13)} Pesan ulang</button><button class="button primary" data-action="close-modal">Selesai</button></div></section></div>`;
