    if (m.type === "notifications") return genericModal("Notifikasi CareNest", "Pembaruan pesanan, bukti layanan, dan status pembayaran.", `<div class="care-row">${icon("calendar",16)}<div class="care-row-copy"><strong>Care plan menunggu layanan</strong><span>Dinda Rahma · ${relativeDate(currentOrder()?.date || localDate(new Date()))} · ${currentOrder()?.time || ""}</span></div></div><div class="care-row">${icon("shieldCheck",16)}<div class="care-row-copy"><strong>Pembayaran dilindungi</strong><span>Dana ditahan hingga Anda mengonfirmasi layanan selesai.</span></div></div><div class="care-row">${icon("sparkle",16)}<div class="care-row-copy"><strong>CareNest siap membantu</strong><span>Laporkan masalah kapan saja lewat Live Care.</span></div></div>`, `<button class="button primary" data-action="navigate" data-view="orders">Buka pesanan</button>`);
    if (m.type === "verification-detail") { const row = adminVerificationRows[Number(m.id)] || adminVerificationRows[0]; return genericModal(`Review dokumen · ${escapeHtml(row.name)}`, "Dokumen disimulasikan; tidak ada KTP atau credential asli.", `<div class="security-illustration">${icon("shieldCheck",26)}</div><div class="setting-row"><div><strong>Identitas</strong><span>Nama cocok · status dokumen demo</span></div>${statusPill("Perlu ditinjau")}</div><div class="setting-row"><div><strong>Dokumen terlampir</strong><span>${escapeHtml(row.type)}</span></div>${icon("lock",14)}</div><div class="inline-notice orange">${icon("shield",14)} Admin harus memeriksa bukti sumber dan mencatat hasil review sebelum memberi badge.</div>`, `<button class="button secondary" data-action="close-modal">Tutup</button><button class="button green" data-action="approve-verification" data-id="${m.id}">Setujui verifikasi</button>`); }
