    if (m.type === "facility-edit") return genericModal("Edit listing fasilitas", "Detail publik yang akurat membantu customer memilih layanan yang tepat.", `<div class="field"><label>Nama fasilitas</label><input id="edit-facility-name" value="${escapeHtml(partnerFacility().name)}"></div><div class="field"><label>Alamat publik / area</label><input id="edit-facility-area" value="${escapeHtml(partnerFacility().area)}"></div><div class="field"><label>Fitur (pisahkan dengan koma)</label><input id="edit-facility-features" value="${escapeHtml(partnerFacility().features.join(", "))}"></div>`, `<button class="button secondary" data-action="close-modal">Batal</button><button class="button primary" data-action="save-facility">Simpan listing</button>`);
    if (m.type === "confirm-complete") return genericModal("Konfirmasi layanan selesai", "Penyelesaian melepaskan dana ke caregiver pada simulasi ini.", `<div class="inline-notice green">${icon("shieldCheck",14)} Semua ${order.tasks.length} task selesai. Pembayaran ${money(order.total)} akan ditandai dicairkan setelah konfirmasi.</div><div class="summary-total"><span>Payout caregiver</span><strong>${money(order.servicePrice)}</strong></div><p class="muted" style="font-size:10px">Apakah layanan berjalan sesuai care plan?</p>`, `<button class="button secondary" data-action="close-modal">Periksa lagi</button><button class="button primary" data-action="confirm-complete" data-id="${order.id}">Konfirmasi selesai</button>`);
