    const order = { id: newOrderId(), type: request.type, route: "home", recipientId: rec.id, recipient: rec.name, recipientAge: rec.age, recipientNote: rec.note, date: request.date, time: request.time, hours: request.hours, package: request.package, tier: request.tier, rate: caregiver.rate, area: request.area, address: request.address, plan: request.plan, caregiverId: caregiver.id, caregiver: caregiver.name, facilityId: null, status: "Dikonfirmasi", payment: "Dana ditahan", servicePrice, fee, total: servicePrice + fee, tasks: createTasks(request), review: null, createdAt: new Date().toISOString(), demo: true };
